int main() {
    std::string inputLine;
    while (std::getline(std::cin, inputLine)) {
        std::istringstream iss(inputLine);
        int totalLength;
        std::string sequence;
        if (!(iss >> totalLength >> sequence)) continue;

        bool insideParentheses = false;
        int totalWords = 0;
        std::string longestSequence = "";
        std::string currentSequence = "";
        bool canCountWord = true;

        for (int i = 0; i < totalLength; ++i) {
            char ch = sequence[i];
            if (ch == '(') {
                insideParentheses = true;
                canCountWord = true;
                currentSequence = "";
            } else if (ch == ')') {
                insideParentheses = false;
                currentSequence = "";
            } else {
                if (!insideParentheses) {
                    if (ch == '_') {
                        currentSequence = "";
                    } else {
                        currentSequence += ch;
                    }
                    if (currentSequence.length() > longestSequence.length()) {
                        longestSequence = currentSequence;
                    }
                } else {
                    if (ch == '_') {
                        canCountWord = true;
                    } else {
                        if (canCountWord) {
                            ++totalWords;
                            canCountWord = false;
                        }
                    }
                }
            }
        }
        std::cout << longestSequence.length() << " " << totalWords << "\n";
